(async()=>{
  const make=async(src)=>{const f=document.createElement('iframe');if(src){f.src=src;await new Promise(r=>{f.onload=r;document.body.appendChild(f)})}else document.body.appendChild(f);return f};
  const out={};
  {
    const f=await make(),w=f.contentWindow,d=w.document,events=[];
    const attached=d.createElement('button'),detached=d.createElement('button'),removed=d.createElement('button'),host=d.createElement('div');
    d.body.append(attached,removed,host);removed.remove();
    const shadow=host.attachShadow({mode:'open'}),shadowButton=d.createElement('button');shadow.append(shadowButton);
    const template=d.createElement('template'),templateButton=d.createElement('button');template.content.append(templateButton);d.body.append(template);
    const standalone=new w.EventTarget();
    for(const [key,target] of [['window',w],['document',d],['attached',attached],['detached',detached],['removed',removed],['shadow',shadowButton],['template',templateButton],['standalone',standalone]]){target.addEventListener('audit',()=>events.push(key));target.onclick=()=>events.push(key+'-onclick')}
    attached.setAttribute('onmousedown','parent.attrFired=true');
    const same=d.open()===d;
    for(const [key,target] of [['window',w],['document',d],['attached',attached],['detached',detached],['removed',removed],['shadow',shadowButton],['template',templateButton],['standalone',standalone]]){target.dispatchEvent(new w.Event('audit'));target.dispatchEvent(new w.Event('click'))}
    out.listeners={same,events,attachedClick:attached.onclick===null,detachedClick:typeof detached.onclick,attribute:attached.getAttribute('onmousedown'),attributeHandler:attached.onmousedown===null};
    d.close();f.remove();
  }
  {
    const f=await make(),w=f.contentWindow,d=w.document,events=[],b=d.createElement('button');d.body.append(b);
    b.addEventListener('audit',()=>{events.push('first');d.open();events.push('opened')});b.addEventListener('audit',()=>events.push('second'));
    b.dispatchEvent(new w.Event('audit'));out.inflight=events;d.close();f.remove();
  }
  {
    const base=document.createElement('base');base.href='/base/';document.head.append(base);
    history.replaceState(null,'','/dir/parent?query#fragment');
    const read=d=>({url:d.URL,base:d.baseURI,location:d.location.href});
    const f=await make('/other/child?child#childFragment'),d=f.contentDocument;
    const before=read(d);d.open();const after=read(d);d.write('<a href="relative">relative</a>');d.close();out.remoteOpen={parent:read(document),before,after,link:d.querySelector('a').href};f.remove();
    const f2=await make('/other/local?child#childFragment');out.localOpen=JSON.parse(f2.contentWindow.eval("(()=>{const before={url:document.URL,base:document.baseURI};document.open();document.write('<a href=relative>relative</a>');document.close();return JSON.stringify({before,after:{url:document.URL,base:document.baseURI},link:document.querySelector('a').href})})()"));f2.remove();
    const f3=await make('/other/implicit?child#childFragment'),d3=f3.contentDocument;const implicitBefore=read(d3);d3.write('<a href=relative>relative</a>');const implicitAfter=read(d3);d3.close();out.implicitWrite={before:implicitBefore,after:implicitAfter,link:d3.querySelector('a').href};f3.remove();base.remove();
  }
  {
    const f=await make(),w=f.contentWindow,d=w.document;w.events=[];d.open();d.write('<p id=before>before</p><script>events.push({step:"start",before:!!document.getElementById("before")});document.open();events.push({step:"open",before:!!document.getElementById("before")});document.write("<p id=nested>nested</p>");document.close();events.push({step:"close",ready:document.readyState});<\/script><p id=after>after</p>');const afterWrite={events:w.events,html:d.body.innerHTML,ready:d.readyState};d.close();out.nested={afterWrite,afterClose:{html:d.body.innerHTML,ready:d.readyState}};f.remove();
  }
  {
    const f=await make(),w=f.contentWindow,d=w.document;globalThis.externalEvents=[];
    const loaded=new Promise(resolve=>f.onload=()=>{externalEvents.push('owner-load');resolve()});
    d.open();d.write('<script src="/external.js"><\/script><p id=first-tail>first-tail</p><script>parent.externalEvents.push("inline-tail")<\/script>');
    const snap=()=>({ready:d.readyState,external:!!d.getElementById('external-written'),firstTail:!!d.getElementById('first-tail'),secondTail:!!d.getElementById('second-tail'),events:externalEvents.slice(),text:d.body?.textContent});
    const afterFirst=snap();d.write('<p id=second-tail>second-tail</p>');const afterSecond=snap();d.close();const afterClose=snap();await loaded;out.external={afterFirst,afterSecond,afterClose,afterLoad:snap(),order:[...d.querySelectorAll('p')].map(n=>n.id)};f.remove();
  }
  {
    const f=await make('/other/call?child#fragment');const fn=f.contentWindow.eval('(function(){document.open();document.close();return document.URL})');out.callOpen=fn();f.remove();
    const timerFrame=await make('/other/timer?child#fragment');const reported=new Promise(resolve=>addEventListener('message',event=>resolve(event.data),{once:true}));
    timerFrame.contentWindow.eval("setTimeout(()=>{document.open();document.close();parent.postMessage(document.URL,'*')},0)");out.timerOpen=await reported;timerFrame.remove();
  }
  return out;
})()
